import 'dart:async';

import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';
import 'package:flutter/widgets.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import 'sound_service.dart';

/// Background loops in `assets/music/`, generated by
/// `tool/generate_music.py`.
enum MusicTrack {
  /// Calm and warm: the map and the tabs.
  map('map_garden'),

  /// Concentration loops for thinking games.
  focusDrift('focus_drift'),
  focusTide('focus_tide'),
  focusGlass('focus_glass'),

  /// Livelier loops for quick reflex games.
  upbeatBounce('upbeat_bounce'),
  upbeatSpark('upbeat_spark');

  const MusicTrack(this.file);

  final String file;
}

/// Plays one looping track at a time, very softly, with short fades.
///
/// Screens ask for music with [MusicScope]; the most recent scope wins and
/// popping it restores the previous one. A scope with a null track means
/// silence (exercises and voice games, so the microphone hears only you).
class MusicService {
  MusicService(this._volume);

  /// User setting 0..1. The loop plays at [_ceiling] of it so it stays
  /// in the background.
  final double Function() _volume;
  static const _ceiling = 0.35;

  final List<(Object, MusicTrack?)> _requests = [];
  AudioPlayer? _player;
  MusicTrack? _playing;
  bool _broken = false;
  bool _paused = false;

  MusicTrack? get wanted => _requests.isEmpty ? null : _requests.last.$2;

  double get _target => (_volume() * _ceiling).clamp(0.0, 1.0);

  void push(Object owner, MusicTrack? track) {
    _requests.removeWhere((r) => r.$1 == owner);
    _requests.add((owner, track));
    _sync();
  }

  void pop(Object owner) {
    _requests.removeWhere((r) => r.$1 == owner);
    _sync();
  }

  /// Retries after a blocked start: browsers refuse audio until the first
  /// user gesture, so the map music starts on the first tap.
  void onUserGesture() {
    if (_playing == null && _desired != null) _sync();
  }

  /// App went to background / came back.
  void setPaused(bool paused) {
    _paused = paused;
    _sync();
  }

  /// The music volume setting changed.
  void volumeChanged() {
    final player = _player;
    if (player == null || _broken) return;
    if (_target <= 0) {
      _sync();
      return;
    }
    if (_playing == null) {
      _sync();
      return;
    }
    unawaited(player.setVolume(_target).catchError((_) {}));
  }

  /// Changes are applied one after another, so quick navigation never
  /// leaves two loops playing.
  Future<void> _chain = Future.value();

  MusicTrack? get _desired => (_paused || _target <= 0) ? null : wanted;

  void _sync() {
    if (_broken) return;
    _chain = _chain.then((_) => _apply()).catchError((Object e) {
      // No audio plugin (tests) or autoplay blocked (web before the first
      // tap): stay quiet and try again on the next request.
      debugPrint('MusicService: $e');
      _playing = null;
      if (e is MissingPluginException) _broken = true;
    });
  }

  Future<void> _apply() async {
    final track = _desired;
    if (_broken || track == _playing) return;
    await configureAudioSession();
    final player = _player ??= AudioPlayer();
    if (_playing != null) {
      await _fade(player, from: _target, to: 0);
      await player.stop();
      _playing = null;
    }
    if (track == null) return;
    await player.setReleaseMode(ReleaseMode.loop);
    await player.setVolume(0);
    await player.play(AssetSource('music/${track.file}.m4a'));
    _playing = track;
    await _fade(player, from: 0, to: _target);
  }

  Future<void> _fade(
    AudioPlayer player, {
    required double from,
    required double to,
  }) async {
    const steps = 8;
    for (var i = 1; i <= steps; i++) {
      await player.setVolume(from + (to - from) * i / steps);
      await Future<void>.delayed(const Duration(milliseconds: 45));
    }
  }

  Future<void> dispose() async {
    await _player?.dispose();
    _player = null;
  }
}

final musicServiceProvider = Provider<MusicService>((ref) {
  final service = MusicService(() => ref.read(audioSettingsProvider).music);
  ref.listen(audioSettingsProvider, (_, _) => service.volumeChanged());
  ref.onDispose(service.dispose);
  return service;
});

/// Declares the music for the subtree while it is mounted. [track] null
/// means silence.
class MusicScope extends ConsumerStatefulWidget {
  const MusicScope({super.key, required this.track, required this.child});

  final MusicTrack? track;
  final Widget child;

  @override
  ConsumerState<MusicScope> createState() => _MusicScopeState();
}

class _MusicScopeState extends ConsumerState<MusicScope>
    with WidgetsBindingObserver {
  late final MusicService _music = ref.read(musicServiceProvider);

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _music.push(this, widget.track);
  }

  @override
  void didUpdateWidget(MusicScope old) {
    super.didUpdateWidget(old);
    if (old.track != widget.track) _music.push(this, widget.track);
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    _music.setPaused(
      state == AppLifecycleState.paused || state == AppLifecycleState.hidden,
    );
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _music.pop(this);
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => Listener(
    behavior: HitTestBehavior.translucent,
    onPointerDown: (_) => _music.onUserGesture(),
    child: widget.child,
  );
}
